CREATE TABLE IF NOT EXISTS courses (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(160) NOT NULL, description VARCHAR(2000) NOT NULL,
 category VARCHAR(100) NOT NULL DEFAULT 'General', level VARCHAR(40) NOT NULL DEFAULT 'INICIAL', price DECIMAL(12,2) NOT NULL DEFAULT 0,
 status VARCHAR(20) NOT NULL DEFAULT 'PUBLISHED', start_date DATE, end_date DATE, image_url VARCHAR(500),
 created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO courses(title,description,category,level,price,status,start_date,image_url) SELECT 'Fundamentos de Java','Aprende sintaxis, orientación a objetos y colecciones con ejercicios prácticos.','Programación','INICIAL',0,'PUBLISHED',CURRENT_DATE,'https://images.unsplash.com/photo-1515879218367-8466d910aaa4' WHERE NOT EXISTS(SELECT 1 FROM courses WHERE title='Fundamentos de Java');
